// Count table rows
const rows = document.querySelectorAll('table tr, [class*="row"]');
const tableRows = document.querySelectorAll('tr');
const tbody = document.querySelector('tbody');
const tbodyRows = tbody ? tbody.querySelectorAll('tr').length : 'no tbody';
const allElements = document.querySelectorAll('*').length;
return {
  totalElements: allElements,
  tableRows: tableRows.length,
  tbodyRows: tbodyRows,
  genericRows: rows.length
};

// Check if there's React or similar framework
const reactRoot = document.getElementById('root');
const hasReact = reactRoot && (reactRoot._reactRootContainer || reactRoot.__reactFiber$ !== undefined);
const reactFiberKey = reactRoot ? Object.keys(reactRoot).find(k => k.startsWith('__reactFiber')) : null;
return { hasReact, reactFiberKey, rootChildren: reactRoot ? reactRoot.children.length : 0 };

// Check for framework markers
const root = document.getElementById('root');
const keys = root ? Object.keys(root).filter(k => k.startsWith('__')) : [];
// Check for Vue, Svelte, etc.
const hasVue = !!document.querySelector('[data-v-]') || !!window.__VUE__;
const hasSvelte = !!document.querySelector('[class*="svelte"]');
// Check the script tags
const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src);
return { keys, hasVue, hasSvelte, scripts };

// Set up a performance observer to monitor re-renders
window.__perfLog = [];
const textarea = document.querySelector('textarea');

// Monkey-patch to detect re-renders - check if React re-renders the table
const observer = new MutationObserver((mutations) => {
  window.__perfLog.push({
    time: performance.now(),
    count: mutations.length,
    types: mutations.map(m => m.type + ':' + (m.target.tagName || '').toLowerCase()).slice(0, 5)
  });
});

observer.observe(document.getElementById('root'), { 
  childList: true, 
  subtree: true, 
  characterData: true,
  attributes: true 
});

window.__mutationObserver = observer;
return 'Observer set up';

// Reset and capture more detailed mutation info
window.__perfLog = [];
window.__mutationObserver.disconnect();

const observer = new MutationObserver((mutations) => {
  const details = mutations.map(m => ({
    type: m.type,
    tag: (m.target.tagName || '').toLowerCase(),
    className: (m.target.className || '').toString().slice(0, 60),
    attr: m.attributeName,
    addedNodes: m.addedNodes.length,
    removedNodes: m.removedNodes.length
  }));
  window.__perfLog.push({
    time: performance.now(),
    count: mutations.length,
    details: details
  });
});

observer.observe(document.getElementById('root'), { 
  childList: true, 
  subtree: true, 
  characterData: true,
  attributes: true 
});

window.__mutationObserver = observer;
return 'Detailed observer set up';

// Measure actual time for a keystroke by dispatching input events manually
const textarea = document.querySelector('textarea');

// Profile a simulated state change
const start = performance.now();

// Dispatch an input event to trigger React's onChange
const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
nativeInputValueSetter.call(textarea, textarea.value + 'x');
textarea.dispatchEvent(new Event('input', { bubbles: true }));

const afterInput = performance.now();

// Wait a moment for React to process
return new Promise(resolve => {
  requestAnimationFrame(() => {
    const afterRender = performance.now();
    resolve({
      inputDispatchTime: afterInput - start,
      totalRenderTime: afterRender - start,
      inputToRender: afterRender - afterInput
    });
  });
});
